    throw new Error("That invitation has already been accepted");
  }
  if (invitation.expiresAt <= toIsoTimestamp(new Date())) {
    throw new Error("That invitation has expired");
  }

  const org = await orgRepo.findOrgById(invitation.orgId);
  if (!org || org.archivedAt !== null) {
    throw new Error("That workspace no longer exists");
  }

  const user = requireFound(await userRepo.findUserById(userId), "User", userId);
  if (user.email.toLowerCase() !== invitation.email.toLowerCase()) {
    throw new Error("That invitation was sent to a different email address");
  }

  const now = toIsoTimestamp(new Date());

  const current = await memberRepo.findMember(invitation.orgId, userId);
  if (current) {
    await invitationRepo.markInvitationAccepted(invitation.orgId, invitation.id, now);
    return current;
  }

  // A former member gets their earlier row back rather than a second one.
  const former = await memberRepo.findMemberIncludingArchived(invitation.orgId, userId);
  const member = former
    ? await memberRepo.restoreMember(invitation.orgId, former.id, {
        role: invitation.role,
        invitedBy: invitation.invitedBy,
        joinedAt: now,
      })
    : await memberRepo.insertMember(
        invitation.orgId,
        userId,
        invitation.role,
        invitation.invitedBy,
      );

  await invitationRepo.markInvitationAccepted(invitation.orgId, invitation.id, now);

  await emit("member.joined", {
    ...envelope(invitation.orgId, userId),
    memberId: member.id,
    userId,
    role: member.role,
  });

  return member;
}

export async function revokeInvitation(
  actor: Actor,
  invitationId: InvitationId,
): Promise<Invitation> {
  assertCan(actor, "member:invite", orgResource(actor.orgId));
  return invitationRepo.revokeInvitation(actor.orgId, invitationId);
}

/**
 * Re-issuing does not mint a new row: the original is revoked and replaced so
 * the audit trail keeps both, and the old link stops working immediately.
 */
export async function resendInvitation(
  actor: Actor,
  invitationId: InvitationId,
): Promise<Invitation> {
  assertOrgScope(actor, actor.orgId);
  assertCan(actor, "member:invite", orgResource(actor.orgId));

  const previous = requireFound(
    await invitationRepo.findInvitationById(actor.orgId, invitationId),
    "Invitation",
    invitationId,
  );
  if (previous.acceptedAt !== null || previous.revokedAt !== null) {
    throw new Error("Only a pending or expired invitation can be sent again");
  }

  await invitationRepo.revokeInvitation(actor.orgId, invitationId);

  // The new link keeps the role the original grant had.
  return inviteMember(actor, {
    orgId: actor.orgId,
    email: previous.email,
    role: invitableRoleSchema.parse(previous.role),
  });
}
